 function select(id,event){if(space||hand||suppressClick)return;const next=new Set(event?.shiftKey?ids:[]);if(event?.shiftKey&&next.has(id))next.delete(id);else next.add(id);set([...next]);}
 function finishNudge(){if(nudgeBefore){api.record(nudgeBefore);nudgeBefore=null;}}
