 function commitTransform(dx,dy,degrees=0,pivot){const list=objects();if(!list.length)return;const b=bounds(list);pivot??={x:b.x+b.width/2,y:b.y+b.depth/2};api.commit(()=>{const moved=transform(list,dx,dy,degrees,pivot);validateObjects(moved,api.model());moved.forEach(o=>Object.assign(list.find(x=>x.id===o.id),o));});}
