 function bindResize(handle,a){handle.visible(api.canEdit());handle.draggable(api.canEdit());handle.on('dragstart',e=>{e.cancelBubble=true;drag={resize:true};});handle.on('dragend',e=>{e.cancelBubble=true;if(cancelling)return;drag=null;api.commit(()=>{const next={...a,width:Math.max(.5,Math.round((handle.x()+5)/unit*2)/2),depth:Math.max(.5,Math.round((handle.y()+5)/unit*2)/2)};validateArea(next);Object.assign(a,next);});});}
 function bindDoor(node,d,b,onSelect){nodes.set('door:'+d.id,node);node.draggable(api.canEdit()&&!space&&!hand);const horizontal=['top','bottom'].includes(d.side);let offset=d.offset;
 node.on('dragstart',e=>{e.cancelBubble=true;finishNudge();onSelect();drag={door:true};suppressClick=true;node.findOne('.door-line')?.stroke('#b28b35');});
 node.on('dragmove',e=>{e.cancelBubble=true;offset=draggedDoorOffset(b,d,(horizontal?node.x():node.y())/unit,!e.evt?.altKey);node.position({x:horizontal?(offset-d.offset)*unit:0,y:horizontal?0:(offset-d.offset)*unit});});
 node.on('dragend',e=>{e.cancelBubble=true;if(cancelling)return;drag=null;api.commit(()=>{const next={...d,offset};validateDoors({...b,doors:b.doors.map(x=>x.id===d.id?next:x)});Object.assign(d,next);});setTimeout(()=>suppressClick=false,0);});
 }
 function worldPoint(){const p=stage.getPointerPosition();return {x:(p.x-stage.x())/stage.scaleX()/unit,y:(p.y-stage.y())/stage.scaleY()/unit};}
 stage.draggable(false);stage.on('mousedown.cad touchstart.cad',e=>{if(space||hand){stage.startDrag();return;}if(!api.canEdit()){if(e.target===stage||e.target.getAttr('cadBackground'))stage.startDrag();return;}if(e.evt?.button&&e.evt.button!==0)return;if(e.target!==stage&&!e.target.getAttr('cadBackground'))return;finishNudge();marquee={start:worldPoint(),screen:stage.getPointerPosition(),add:!!e.evt.shiftKey,previous:[...ids]};});
 stage.on('mousemove.cad touchmove.cad',()=>{if(!marquee)return;const p=worldPoint(),s=marquee.start;overlay.destroyChildren();overlay.add(new Konva.Rect({x:Math.min(s.x,p.x)*unit,y:Math.min(s.y,p.y)*unit,width:Math.abs(p.x-s.x)*unit,height:Math.abs(p.y-s.y)*unit,fill:p.x>=s.x?'#c9e4f544':'#b9dfce44',stroke:p.x>=s.x?'#6196b5':'#349078',strokeWidth:1/stage.scaleX(),dash:p.x<s.x?[5/stage.scaleX(),3/stage.scaleX()]:undefined}));overlay.batchDraw();});
 stage.on('mouseup.cad touchend.cad',()=>{if(!marquee)return;const m=marquee,p=worldPoint(),s=m.start;marquee=null;overlay.destroyChildren();const picked=Math.hypot((p.x-s.x)*unit*stage.scaleX(),(p.y-s.y)*unit*stage.scaleY())<4?[]:boxSelect(editable(),{x:Math.min(s.x,p.x),y:Math.min(s.y,p.y),width:Math.abs(p.x-s.x),depth:Math.abs(p.y-s.y),rotation:0},p.x<s.x);set(m.add?[...m.previous,...picked]:picked);});
 function updatePan(){stage.draggable(space||hand);nodes.forEach(n=>n.draggable(api.canEdit()&&!space&&!hand));api.host.style.cursor=space||hand?'grab':'default';$('#pan-tool').classList.toggle('active',hand);}
 function render(){ids=new Set([...ids].filter(id=>editable().some(o=>o.id===id)));const n=ids.size;$('#selection-count').textContent=n?`已选 ${n} 项`:'未选择';for(const id of ['precise-open','array-open','selection-copy','selection-delete','focus-selection'])$('#'+id).disabled=!n||(id!=='focus-selection'&&api.view()!=='2d');$('#pan-tool').disabled=api.view()!=='2d';$('#batch-inspector').hidden=n<2;if(n>1){$('#rack-inspector').hidden=true;$('#spatial-inspector').hidden=true;$('#batch-count').textContent=`已选择 ${n} 个对象`;const b=bounds(objects());$('#batch-size').textContent=`组合范围 ${b.width.toFixed(2)} × ${b.depth.toFixed(2)} 米；移动和旋转会保持相对位置。`;}}
 function focus(){const list=objects(),external=api.externalBounds?.();if(!list.length&&!external){api.toast('请先选择货架、区域或门');return;}api.focus(list.length?bounds(list):external);}
 function showPrecise(){if(api.view()!=='2d'||!objects().length)return;$('#precise-form').reset();$('#precise-error').textContent='';const b=bounds(objects());$('#pivot-x').value=(b.x+b.width/2).toFixed(3);$('#pivot-y').value=(b.y+b.depth/2).toFixed(3);$('#precise-dialog').showModal();}
 $('#precise-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const list=objects(),b=bounds(list),pivot=f.get('pivot')==='custom'?{x:Number(f.get('px')),y:Number(f.get('py'))}:{x:b.x+b.width/2,y:b.y+b.depth/2};try{const next=transform(list,Number(f.get('dx')),Number(f.get('dy')),Number(f.get('angle')),pivot);validateObjects(next,api.model());commitTransform(Number(f.get('dx')),Number(f.get('dy')),Number(f.get('angle')),pivot);$('#precise-dialog').close();}catch(err){$('#precise-error').textContent=err.message;}};
 function arrayPreview(){try{const f=new FormData($('#array-form')),offsets=arrayOffsets(objects(),Number(f.get('rows')),Number(f.get('cols')),Number(f.get('gapX')),Number(f.get('gapY')));if(!offsets.length)throw Error('行列数包含原件，请至少设为 1 行 2 列或 2 行 1 列');const candidate=copies(objects(),offsets,api.model());$('#array-error').textContent='';$('#array-summary').textContent=`保留原件，新增 ${candidate.length} 个对象。按世界 X/Y 方向排列，净间距以每组外包矩形计算。`;$('#array-confirm').disabled=false;overlay.destroyChildren();for(const o of candidate)overlay.add(new Konva.Line({points:corners(o).flatMap(p=>[p.x*unit,p.y*unit]),closed:true,stroke:'#b18a35',fill:'#f9e6a833',strokeWidth:1/stage.scaleX(),dash:[5/stage.scaleX(),3/stage.scaleX()]}));overlay.batchDraw();return offsets;}catch(err){$('#array-error').textContent=err.message;$('#array-confirm').disabled=true;overlay.destroyChildren();return null;}}
 function showArray(){if(api.view()!=='2d'||!objects().length)return;$('#array-form').reset();$('#array-dialog').showModal();arrayPreview();}
 $('#array-form').oninput=arrayPreview;$('#array-form').onsubmit=e=>{e.preventDefault();const offsets=arrayPreview();if(offsets){duplicate(offsets);$('#array-dialog').close();}};$('#array-dialog').addEventListener('close',()=>overlay.destroyChildren());
 for(const d of document.querySelectorAll('dialog')){d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.addEventListener('close',()=>{api.host.focus({preventScroll:true});});}
 $('#precise-open').onclick=showPrecise;$('#array-open').onclick=showArray;$('#selection-copy').onclick=()=>duplicate();$('#selection-delete').onclick=remove;$('#focus-selection').onclick=focus;$('#shortcut-help').onclick=()=>$('#shortcuts-dialog').showModal();$('#pan-tool').onclick=()=>{hand=!hand;updatePan();};
 function keydown(e){const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(dialog())return;if(mod&&key==='s'){e.preventDefault();finishNudge();$('#save').click();return;}if(isInput(e))return;if(key==='escape'){e.preventDefault();if(drag||marquee||nudgeBefore)cancel();else set([]);return;}if(mod&&['z','y'].includes(key)){e.preventDefault();finishNudge();(key==='y'||e.shiftKey?$('#redo'):$('#undo')).click();return;}if(e.key==='?'||e.key==='F1'){e.preventDefault();$('#shortcuts-dialog').showModal();return;}if(key==='home'){e.preventDefault();api.fit();return;}if(key==='f'&&!mod){e.preventDefault();focus();return;}if(api.view()!=='2d')return;if(e.code==='Space'){e.preventDefault();space=true;updatePan();return;}if(!api.canEdit()){if((mod&&key==='d')||e.key==='Delete'||e.key.startsWith('Arrow'))e.preventDefault();return;}if(mod&&key==='d'){e.preventDefault();if(!e.repeat){finishNudge();duplicate();}return;}if(e.key==='Delete'){e.preventDefault();if(!e.repeat){finishNudge();remove();}return;}if(['q','e'].includes(key)&&!mod){e.preventDefault();if(!e.repeat){finishNudge();commitTransform(0,0,key==='q'?-90:90);}return;}const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(delta&&objects().length){e.preventDefault();if(drag)return;nudgeBefore??=JSON.stringify(api.model());const step=e.shiftKey?1:.1;try{const moved=transform(objects(),delta[0]*step,delta[1]*step,0,{x:0,y:0});validateObjects(moved,api.model());moved.forEach(o=>Object.assign(editable().find(x=>x.id===o.id),o));api.render();}catch(err){api.toast(err.message);}}}
 window.addEventListener('keydown',keydown);window.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;updatePan();}if(e.key.startsWith('Arrow'))finishNudge();});window.addEventListener('blur',()=>{finishNudge();space=false;updatePan();if(drag||marquee)cancel();});
 // End a key-repeat command before any subsequent pointer command can enter history.
